create or replace function public.ensure_signup_profile(p_display_name text default null, p_username text default null, p_avatar_url text default null, p_bio text default null, p_is_demo_test boolean default false) returns jsonb language plpgsql security definer set search_path to 'public','pg_temp' as $$ declare v_user uuid:=auth.uid(); v_email text; v_profile jsonb; begin if v_user is null then raise exception 'not_authenticated'; end if; select email into v_email from auth.users where id=v_user; insert into public.profiles(id,email,display_name,username,avatar_url,bio,is_demo_test) values(v_user,v_email,coalesce(nullif(p_display_name,''),split_part(coalesce(v_email,''),'@',1)),nullif(p_username,''),p_avatar_url,p_bio,p_is_demo_test) on conflict(id) do update set email=excluded.email,display_name=coalesce(nullif(excluded.display_name,''),public.profiles.display_name),username=coalesce(excluded.username,public.profiles.username),avatar_url=coalesce(excluded.avatar_url,public.profiles.avatar_url),bio=coalesce(excluded.bio,public.profiles.bio),is_demo_test=public.profiles.is_demo_test or excluded.is_demo_test,updated_at=now(); select to_jsonb(p) into v_profile from public.profiles p where p.id=v_user; return jsonb_build_object('profile',v_profile,'demo',p_is_demo_test); end; $$;

create or replace function public.admin_set_account_capabilities(p_target_user_id uuid, p_role text default null, p_subscription_tier text default null, p_is_business_user boolean default null, p_is_admin boolean default null, p_is_demo_test boolean default null, p_reason text default null) returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare caller uuid:=auth.uid(); before_state jsonb; after_state jsonb; begin if caller is null then raise exception 'authentication required'; end if; if not exists(select 1 from public.profiles where id=caller and is_admin=true) then raise exception 'admin authorization required'; end if; if p_target_user_id is null then raise exception 'target user required'; end if; select jsonb_build_object('role',role,'subscription_tier',subscription_tier,'is_business_user',is_business_user,'is_admin',is_admin,'is_demo_test',is_demo_test) into before_state from public.profiles where id=p_target_user_id for update; if before_state is null then raise exception 'target profile not found'; end if; if p_is_admin=false and p_target_user_id=caller then raise exception 'cannot remove your own admin access'; end if; update public.profiles set role=case when p_role is null then role else p_role::public.app_role end,subscription_tier=case when p_subscription_tier is null then subscription_tier else p_subscription_tier::public.subscription_tier end,is_business_user=coalesce(p_is_business_user,is_business_user),is_admin=coalesce(p_is_admin,is_admin),is_demo_test=coalesce(p_is_demo_test,is_demo_test),updated_at=now() where id=p_target_user_id; select jsonb_build_object('role',role,'subscription_tier',subscription_tier,'is_business_user',is_business_user,'is_admin',is_admin,'is_demo_test',is_demo_test) into after_state from public.profiles where id=p_target_user_id; insert into public.admin_capability_audit(admin_user_id,target_user_id,previous_state,new_state,reason) values(caller,p_target_user_id,before_state,after_state,coalesce(p_reason,'Admin account repair')); return after_state; end; $$;

grant execute on function public.ensure_signup_profile(text,text,text,text,boolean) to authenticated;
grant execute on function public.admin_set_account_capabilities(uuid,text,text,boolean,boolean,boolean,text) to authenticated;
